export function validateOciRegistryEndpoint(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "hostname")) fail(contract, `${path}.hostname`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "hostname": {
          if (typeof item !== "string") fail(contract, `${path}.hostname`, "expected string");
          if ((item as string).length < 3) fail(contract, `${path}.hostname`, "must contain at least 3 characters");
          if ((item as string).length > 253) fail(contract, `${path}.hostname`, "must contain at most 253 characters");
          break;
        }
        case "port": {
          if (typeof item !== "number" || !Number.isFinite(item)) fail(contract, `${path}.port`, "expected finite number");
          if (!Number.isInteger(item)) fail(contract, `${path}.port`, "expected integer");
          if ((item as number) < 1.0) fail(contract, `${path}.port`, "must be >= 1.0");
          if ((item as number) > 65535.0) fail(contract, `${path}.port`, "must be <= 65535.0");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

